<template><view class="page"><view class="notice">当前仅支持已完成入库的调拨单。区县代审核通过后会冻结所选库存，寄回并确认收货后库存回流，最后由区县代确认线下退款。</view><view v-if="transfer" class="card"><text>原调拨单：{{transfer.transferNo}}</text><text>可申请金额以原调拨单价和实际退回数量计算</text></view><view class="card"><view class="title">选择退回商品</view><view v-for="item in items" :key="item.id" class="line"><view><text>{{item.productName||'商品已删除'}}</text><text class="muted">{{item.skuText||item.skuName||'默认规格'}} / 原数量 {{item.quantity}}</text></view><input v-model.number="item.returnQuantity" type="number" :placeholder="'0-'+item.quantity"/></view></view><view class="card"><text class="label">退回原因</text><textarea v-model="reason" placeholder="请说明退回原因和商品情况"/><button type="primary" :disabled="submitting" @click="submit">提交退回申请</button></view></view></template>
<script>import{getJkStockTransferDetail,createJkStockTransferReturn}from'@/api/jk.js';export default{data(){return{id:0,transfer:null,items:[],reason:'',submitting:false}},onLoad(q){this.id=Number(q.transferId||q.id);getJkStockTransferDetail(this.id).then(r=>{const p=r.data||r;this.transfer=p.transfer;this.items=(p.items||[]).map(x=>({...x,returnQuantity:0}))})},methods:{submit(){const rows=this.items.filter(x=>Number(x.returnQuantity)>0).map(x=>({originalTransferItemId:x.id,quantity:Number(x.returnQuantity)}));if(!rows.length)return this.$util.Tips({title:'请选择退回数量'});if(!this.reason.trim())return this.$util.Tips({title:'请填写退回原因'});this.submitting=true;createJkStockTransferReturn({requestNo:'RETURN-'+Date.now(),originalTransferId:this.id,returnReason:this.reason.trim(),items:rows}).then(()=>this.$util.Tips({title:'退回申请已提交',icon:'success'},{tab:5,url:'/pages/jk/return/list?mode=own'})).finally(()=>this.submitting=false)}}}</script>
<style scoped>.page{min-height:100vh;background:#f3f8f6;padding:24rpx}.notice,.card{margin-bottom:18rpx;padding:26rpx;border-radius:20rpx;background:#fff;color:#567168;line-height:1.7}.notice{background:#fff8e8;color:#936a20}.title,.label{display:block;margin-bottom:16rpx;color:#28594a;font-size:29rpx;font-weight:650}.line{display:flex;justify-content:space-between;align-items:center;padding:18rpx 0;border-bottom:1rpx solid #edf2f0}.line input{width:150rpx;padding:14rpx;border-radius:12rpx;background:#f3f6f5;text-align:center}.muted{display:block;color:#93a39d;font-size:24rpx}textarea{width:100%;height:180rpx;box-sizing:border-box;padding:20rpx;border-radius:14rpx;background:#f3f6f5}button{margin-top:28rpx}</style>
